mapper.select:
select fj.id, fj.laoren_id as laorenId, l.xingming as laorenXingming, hr.xingming as huliRenyuanXingming, yp.yaopin_mingcheng as yaopinMingcheng, yp.guige, fj.jihua_shijian as jihuaShijian, fj.shiji_shijian as shijiShijian, fj.zhixing_zhuangtai as zhixingZhuangtai, fj.beizhu from fuyao_jilu fj join laoren_xinxi l on fj.laoren_id = l.id join yaopin_xinxi yp on fj.yaopin_id = yp.id left join huli_renyuan hr on fj.huli_renyuan_id = hr.id
and l.xingming like concat('%', #{laorenXingming}, '%')
and yp.yaopin_mingcheng like concat('%', #{yaopinMingcheng}, '%')
and fj.zhixing_zhuangtai = #{zhixingZhuangtai}
and date(fj.jihua_shijian) = #{riqi}
order by fj.jihua_shijian desc, fj.id desc
